def seed_week(apps, schema_editor):
    """Start from the hours the site has always shown: Mon–Fri 9–6, Sat 9–4,
    closed Sunday. Barbers change them from the dashboard after this."""
    ShopHours = apps.get_model("core", "ShopHours")
    for day in range(7):
        is_open = day != 6
        close = time(16) if day == 5 else time(18)
        ShopHours.objects.get_or_create(
            day_of_week=day,
            defaults={"is_open": is_open, "open_time": time(9), "close_time": close},
        )


